WITH windows AS (SELECT 0 AS sample, 18775 AS pid, 10313070000000 AS start_ns, 10314839518041 AS end_ns UNION ALL SELECT 1 AS sample, 18775 AS pid, 10316490000000 AS start_ns, 10318136363916 AS end_ns UNION ALL SELECT 2 AS sample, 18775 AS pid, 10319020000000 AS start_ns, 10320683142500 AS end_ns UNION ALL SELECT 3 AS sample, 18775 AS pid, 10321600000000 AS start_ns, 10323313241165 AS end_ns UNION ALL SELECT 4 AS sample, 18775 AS pid, 10324300000000 AS start_ns, 10325950848999 AS end_ns UNION ALL SELECT 5 AS sample, 18775 AS pid, 10326780000000 AS start_ns, 10328456944625 AS end_ns UNION ALL SELECT 6 AS sample, 18775 AS pid, 10329270000000 AS start_ns, 10330952324416 AS end_ns UNION ALL SELECT 7 AS sample, 18775 AS pid, 10331800000000 AS start_ns, 10333459720375 AS end_ns UNION ALL SELECT 8 AS sample, 18775 AS pid, 10334560000000 AS start_ns, 10336251113540 AS end_ns UNION ALL SELECT 9 AS sample, 18775 AS pid, 10337170000000 AS start_ns, 10338836292624 AS end_ns UNION ALL SELECT 10 AS sample, 18775 AS pid, 10339570000000 AS start_ns, 10341274754250 AS end_ns UNION ALL SELECT 11 AS sample, 18775 AS pid, 10342460000000 AS start_ns, 10344142857291 AS end_ns UNION ALL SELECT 12 AS sample, 18775 AS pid, 10344870000000 AS start_ns, 10346515651166 AS end_ns UNION ALL SELECT 13 AS sample, 18775 AS pid, 10347340000000 AS start_ns, 10349076545083 AS end_ns UNION ALL SELECT 14 AS sample, 18775 AS pid, 10349920000000 AS start_ns, 10351558665290 AS end_ns UNION ALL SELECT 15 AS sample, 18775 AS pid, 10352400000000 AS start_ns, 10354086081250 AS end_ns UNION ALL SELECT 16 AS sample, 18775 AS pid, 10354910000000 AS start_ns, 10356587459875 AS end_ns UNION ALL SELECT 17 AS sample, 18775 AS pid, 10357560000000 AS start_ns, 10359230157582 AS end_ns UNION ALL SELECT 18 AS sample, 18775 AS pid, 10360110000000 AS start_ns, 10361773306249 AS end_ns UNION ALL SELECT 19 AS sample, 18775 AS pid, 10362560000000 AS start_ns, 10364310541000 AS end_ns UNION ALL SELECT 20 AS sample, 18775 AS pid, 10365540000000 AS start_ns, 10367187361457 AS end_ns UNION ALL SELECT 21 AS sample, 18775 AS pid, 10368070000000 AS start_ns, 10369743266000 AS end_ns UNION ALL SELECT 22 AS sample, 18775 AS pid, 10370830000000 AS start_ns, 10372492480540 AS end_ns UNION ALL SELECT 23 AS sample, 18775 AS pid, 10373280000000 AS start_ns, 10374931612791 AS end_ns UNION ALL SELECT 24 AS sample, 18775 AS pid, 10375750000000 AS start_ns, 10377420022749 AS end_ns UNION ALL SELECT 25 AS sample, 18775 AS pid, 10378310000000 AS start_ns, 10380014678250 AS end_ns UNION ALL SELECT 26 AS sample, 18775 AS pid, 10380920000000 AS start_ns, 10382578984375 AS end_ns UNION ALL SELECT 27 AS sample, 18775 AS pid, 10383420000000 AS start_ns, 10385081707375 AS end_ns UNION ALL SELECT 28 AS sample, 18775 AS pid, 10385990000000 AS start_ns, 10387638542625 AS end_ns UNION ALL SELECT 29 AS sample, 18775 AS pid, 10388660000000 AS start_ns, 10390335484333 AS end_ns UNION ALL SELECT 30 AS sample, 18775 AS pid, 10391220000000 AS start_ns, 10392885140249 AS end_ns UNION ALL SELECT 31 AS sample, 18775 AS pid, 10393810000000 AS start_ns, 10395519676374 AS end_ns UNION ALL SELECT 32 AS sample, 18775 AS pid, 10396580000000 AS start_ns, 10398224201000 AS end_ns UNION ALL SELECT 33 AS sample, 18775 AS pid, 10399130000000 AS start_ns, 10400802480417 AS end_ns UNION ALL SELECT 34 AS sample, 18775 AS pid, 10401590000000 AS start_ns, 10403251392583 AS end_ns UNION ALL SELECT 35 AS sample, 18775 AS pid, 10404040000000 AS start_ns, 10405704171917 AS end_ns)
SELECT w.sample, count(*) AS app_frame_records,
 sum(CASE WHEN a.jank_type LIKE '%App Deadline Missed%' THEN 1 ELSE 0 END) AS app_deadline_misses,
 sum(CASE WHEN a.jank_type != 'None' THEN 1 ELSE 0 END) AS all_jank_records,
 sum(CASE WHEN a.present_type = 'Dropped Frame' THEN 1 ELSE 0 END) AS dropped_frame_records,
 round(avg(a.dur)/1e6,2) AS mean_actual_frame_ms,
 round(max(a.dur)/1e6,2) AS max_actual_frame_ms,
 group_concat(a.dur) AS actual_durations_ns
FROM windows w JOIN process p ON p.pid=w.pid
JOIN actual_frame_timeline_slice a ON a.upid=p.upid
WHERE a.ts >= w.start_ns AND a.ts < w.end_ns AND a.dur > 0
GROUP BY w.sample ORDER BY w.sample